-- GRAIN: one row per provider (CCN+NPI+YEAR+OWNERSHIP_TYPE+MEASURE_ID unique)
-- SPINE_ENTITY: provider  (natural_key: CCN, NPI, YEAR, OWNERSHIP_TYPE, MEASURE_ID)
-- Generated by scripts/generate_staging_models.py from SOURCE_REGISTRY -- deterministic,
-- no LLM. Casts kept as landed (TEXT) -- add explicit type casts by hand once each
-- column's real type is confirmed; this generator has no semantic type knowledge.
-- spine_entity 'provider' has no connect/ resolver yet (see connect/spine_entity.py) -- no SPINE_ENTITY_ID emitted.

with source as (

    select * from {{ source('ripple_raw', 'FED_CMS_MEDICARE_DIALYSIS_FACILITIES') }}

),

renamed as (

    select
        "STATE" as state,
        "CCN" as ccn,
        "PROVIDER_NAME" as provider_name,
        "CITY" as city,
        "OWNERSHIP_TYPE" as ownership_type,
        "ESRD_NETWORK" as esrd_network,
        "NPI" as npi,
        "CHAIN" as chain,
        "MODALITY" as modality,
        "ALTERNATE_CCNS" as alternate_ccns,
        "MEASURE" as measure,
        "MEASURE_SCORE" as measure_score,
        "YEAR" as year,
        "MEASURE_ID" as measure_id,
        _INGESTED_AT as _loaded_at,
        '' as _source_url

    from source

)

select * from renamed
qualify row_number() over (partition by ccn, npi, year, ownership_type, measure_id order by _loaded_at desc) = 1
